  annotations:
    gridcast.dev/description: "Builds forecast features from raw data"
spec:
  replicas: 1
  revisionHistoryLimit: 10
  strategy: { type: RollingUpdate, rollingUpdate: { maxUnavailable: 0, maxSurge: 1 } }
  selector: { matchLabels: { app.kubernetes.io/name: feature-service } }
