    metadata:
      labels: { app.kubernetes.io/name: feature-service, app.kubernetes.io/component: features, app.kubernetes.io/part-of: gridcast }
    spec:
      terminationGracePeriodSeconds: 20
      securityContext: { runAsNonRoot: true, runAsUser: 10001, seccompProfile: { type: RuntimeDefault } }
      containers:
        - name: feature-service
          imagePullPolicy: Always  # dev registry: tags may be rebuilt
          image: gridcast/feature-service
          args: ["serve", "feature-service"]
          ports: [{ name: http, containerPort: 8080 }]
          envFrom:
            - configMapRef: { name: gridcast-runtime }
          env:
            - name: GRIDCAST_DB_USER
              valueFrom: { secretKeyRef: [REDACTED_SECRET] name: db-app, key: username } }
            - name: GRIDCAST_DB_PASSWORD
              valueFrom: { secretKeyRef: [REDACTED_SECRET] name: db-app, key: password } }
            - name: K8S_POD_NAME
              valueFrom: { fieldRef: { fieldPath: metadata.name } }
            - name: K8S_NAMESPACE
              valueFrom: { fieldRef: { fieldPath: metadata.namespace } }
            - name: K8S_NODE_NAME
              valueFrom: { fieldRef: { fieldPath: spec.nodeName } }
            - { name: K8S_DEPLOYMENT_NAME, value: feature-service }
          readinessProbe: { httpGet: { path: /readyz, port: http }, periodSeconds: 10, failureThreshold: 3 }
          livenessProbe: { httpGet: { path: /healthz, port: http }, periodSeconds: 20, timeoutSeconds: 5, failureThreshold: 3 }
          startupProbe: { httpGet: { path: /healthz, port: http }, periodSeconds: 5, failureThreshold: 60 }
          resources:
            requests: { cpu: 100m, memory: 192Mi }
            limits: { cpu: "1", memory: 512Mi }
          securityContext: { allowPrivilegeEscalation: false, readOnlyRootFilesystem: true, capabilities: { drop: [ALL] } }
          volumeMounts: [{ name: tmp, mountPath: /tmp }]
      volumes: [{ name: tmp, emptyDir: {} }]
